// ------------------------------------------------------------------
// Font Loader (Standard Requirement)
// ------------------------------------------------------------------
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// ------------------------------------------------------------------
// Schema & Types
// ------------------------------------------------------------------


export type MadScienceLabProps = Record<string, any>;

// ------------------------------------------------------------------
// Sub-Components (Bubbles, Steam, Containers)
// ------------------------------------------------------------------

const Bubble: React.FC<{
  seed: number;
  color: string;
  containerHeight: number;
  delay: number;
}> = ({ seed, color, containerHeight, delay }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Each bubble has its own cycle duration
  const cycleDuration = 30 + Math.floor(random(seed) * 30);
  const offsetFrame = frame - delay;
  
  // Only render if active cycle
  const progress = (offsetFrame % cycleDuration) / cycleDuration;
  
  if (offsetFrame < 0) return null;

  const y = interpolate(progress, [0, 1], [0, -containerHeight * 0.8]);
  const scale = interpolate(progress, [0, 0.5, 1], [0.5, 1.2, 0]);
  const xWobble = Math.sin(frame / 5 + seed) * 5;
  const x = (random(seed + 1) - 0.5) * 40 + xWobble;

  return (
    <div
      style={{
        position: "absolute",
        bottom: 20,
        left: "50%",
        width: 12,
        height: 12,
        borderRadius: "50%",
        backgroundColor: color,
        opacity: 0.7,
        transform: `translate(calc(-50% + ${x}px), ${y}px) scale(${scale})`,
        border: "1px solid rgba(255,255,255,0.4)",
      }}
    />
  );
};

const BubblingLiquid: React.FC<{
  width: number;
  height: number;
  color: string;
  bubbleCount: number;
}> = ({ width, height, color, bubbleCount }) => {
  const seeds = useMemo(
    () => new Array(bubbleCount).fill(0).map((_, i) => i),
    [bubbleCount]
  );

  return (
    <div
      style={{
        width: "100%",
        height: "100%",
        position: "relative",
        overflow: "hidden",
      }}
    >
      <AbsoluteFill style={{ backgroundColor: color, opacity: 0.8 }} />
      {seeds.map((i) => (
        <Bubble
          key={i}
          seed={i}
          color="rgba(255,255,255,0.5)"
          containerHeight={height}
          delay={i * 5}
        />
      ))}
    </div>
  );
};

const SteamPuff: React.FC<{ x: number; y: number; delay: number }> = ({
  x,
  y,
  delay,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  
  const startFrame = delay;
  const duration = 50;
  
  // Loop the steam effect
  const activeFrame = (frame - startFrame) % 90; // 90 frame loop
  
  if (activeFrame < 0 || activeFrame > duration) return null;

  const opacity = interpolate(
    activeFrame,
    [0, 10, 40, duration],
    [0, 0.6, 0.3, 0],
    { extrapolateRight: "clamp" }
  );

  const translateY = interpolate(activeFrame, [0, duration], [0, -60]);
  const scale = interpolate(activeFrame, [0, duration], [0.5, 1.5]);

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        transform: `translate(-50%, ${translateY}px) scale(${scale})`,
        opacity,
      }}
    >
      <Circle radius={15} fill="#f0f0f0" />
      <div style={{ position: "absolute", left: -12, top: -10 }}>
        <Circle radius={10} fill="#f0f0f0" />
      </div>
      <div style={{ position: "absolute", left: 12, top: -8 }}>
        <Circle radius={12} fill="#f0f0f0" />
      </div>
    </div>
  );
};

